const upsertEdge = `-- name: UpsertEdge :one
INSERT INTO workflow_edges (from_step_id, outcome, to_step_id, max_iterations)
VALUES (?, ?, ?, ?)
ON CONFLICT(from_step_id, outcome) DO UPDATE
SET to_step_id     = excluded.to_step_id,
    max_iterations = excluded.max_iterations
RETURNING id, from_step_id, outcome, to_step_id, max_iterations
`

type UpsertEdgeParams struct {
	FromStepID    int64
	Outcome       string
	ToStepID      int64
	MaxIterations sql.NullInt64
}

// One edge per (from_step, outcome): re-adding an outcome re-routes it.
// DO UPDATE rather than DO NOTHING so RETURNING always yields the row.
func (q *Queries) UpsertEdge(ctx context.Context, arg UpsertEdgeParams) (WorkflowEdge, error) {
	row := q.db.QueryRowContext(ctx, upsertEdge,
		arg.FromStepID,
		arg.Outcome,
		arg.ToStepID,
		arg.MaxIterations,
	)
	var i WorkflowEdge
	err := row.Scan(
		&i.ID,
		&i.FromStepID,
		&i.Outcome,
		&i.ToStepID,
		&i.MaxIterations,
	)
	return i, err
}
